use vstd::prelude::*;

verus! {
    // find_median returns the "median" of two equally‐sized, nondecreasing arrays a and b.
    //
    // If the common length n is odd, we return the middle element of a,
    // i.e. a[n/2].
    //
    // If n is even, we return the integer average
    //   (a[n/2−1] + b[0]) / 2
    // using Rust's integer‐division semantics.
    fn find_median(a: &[i32], b: &[i32]) -> (median: i32)
        requires
            // nonempty, equal length
            a.len() > 0,
            a.len() == b.len(),
            // a sorted in nondecreasing order
            forall(|i: usize| i + 1 < a.len() ==> a[i] <= a[i+1]),
            // b sorted in nondecreasing order
            forall(|i: usize| i + 1 < b.len() ==> b[i] <= b[i+1]),
        ensures
            // specification of the two cases
            if a.len() % 2 == 1 {
                // odd length ⇒ middle of a
                median == a[a.len() / 2]
            } else {
                // even length ⇒ average of last of lower half of a and first of b
                let half = a.len() / 2;
                median == (a[half - 1] + b[0]) / 2
            },
    {
        let n = a.len();
        if n % 2 == 1 {
            // odd case
            median = a[n / 2];
        } else {
            // even case
            let half = n / 2;
            let x = a[half - 1];
            let y = b[0];
            median = (x + y) / 2;
        }
    }

    // A small test
    proof fn test_find_median_odd() {
        let v1 = vec![10, 20, 30].view();
        let v2 = vec![40, 50, 60].view();
        assert(find_median(v1, v2) == 20);
    }

    proof fn test_find_median_even() {
        let v1 = vec![-3, -1, 1, 3].view();
        let v2 = vec![5, 7, 9, 11].view();
        // (v1[4/2 - 1] + v2[0]) / 2 == (v1[1] + v2[0]) / 2 == (-1 + 5) / 2 == 2
        assert(find_median(v1, v2) == 2);
    }
}

